SELECT Trip.id, Company.name
FROM Trip
JOIN Company ON Trip.company = Company.id;

SELECT company, COUNT(*) AS trips
FROM Trip
GROUP BY company;

SELECT name, birth_date
FROM Passenger
ORDER BY birth_date DESC;

SELECT * FROM Pass_in_trip
ORDER BY price DESC
LIMIT 1;

SELECT * FROM Trip
WHERE town_from = 'Moscow'
  AND (town_to = 'Paris' OR town_to = 'London');

SELECT SUM(price), AVG(price),
       MIN(price), MAX(price)
FROM Pass_in_trip;

SELECT name FROM Company
UNION
SELECT name FROM Country;

SELECT company, ARRAY_AGG(id)
FROM Trip
GROUP BY company;

SELECT * FROM Passenger
ORDER BY RANDOM()
LIMIT 3;

SELECT name,
       ROW_NUMBER() OVER (ORDER BY birth_date) AS n
FROM Passenger;
